import re
from typing import Callable, Dict, List, Optional, Tuple, Type, Union
import torch
import torch.nn as nn
from timm.data import IMAGENET_DEFAULT_MEAN, IMAGENET_DEFAULT_STD
from timm.layers import ClassifierHead, ConvNormAct, DropPath, EffectiveSEModule, calculate_drop_path_rates, get_device_dtype
from ._builder import build_model_with_cfg
from ._features import feature_take_indices
from ._manipulate import MATCH_PREV_GROUP, checkpoint, checkpoint_seq
from ._registry import generate_default_cfgs, register_model

class SPPBottleneck(nn.Module):

    def __init__(self, in_channels, out_channels, kernel_sizes=(5, 9, 13), norm_layer=nn.BatchNorm2d, act_layer=nn.SiLU, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        mid_channels = in_channels // 2
        self.conv1 = ConvNormAct(in_channels, mid_channels, 1, norm_layer=norm_layer, act_layer=act_layer, **dd)
        self.poolings = nn.ModuleList([nn.MaxPool2d(k, stride=1, padding=k // 2) for k in kernel_sizes])
        self.conv2 = ConvNormAct(mid_channels * (len(kernel_sizes) + 1), out_channels, 1, norm_layer=norm_layer, act_layer=act_layer, **dd)

    def forward(self, x):
        x = self.conv1(x)
        x = torch.cat([x] + [pool(x) for pool in self.poolings], dim=1)
        return self.conv2(x)

class DepthwiseSeparableConv(nn.Module):

    def __init__(self, in_channels, out_channels, kernel_size, padding=0, dilation=1, norm_layer=nn.BatchNorm2d, act_layer=nn.SiLU, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.depthwise_conv = ConvNormAct(in_channels, in_channels, kernel_size, padding=padding, dilation=dilation, groups=in_channels, norm_layer=norm_layer, act_layer=act_layer, **dd)
        self.pointwise_conv = ConvNormAct(in_channels, out_channels, 1, norm_layer=norm_layer, act_layer=act_layer, **dd)

    def forward(self, x):
        return self.pointwise_conv(self.depthwise_conv(x))

class CspNextBlock(nn.Module):

    def __init__(self, in_channels, out_channels, add_identity=True, kernel_size=5, dilation=1, drop_path=0.0, norm_layer=nn.BatchNorm2d, act_layer=nn.SiLU, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        self.conv1 = ConvNormAct(in_channels, out_channels, 3, padding=dilation, dilation=dilation, norm_layer=norm_layer, act_layer=act_layer, **dd)
        self.conv2 = DepthwiseSeparableConv(out_channels, out_channels, kernel_size, padding=dilation * (kernel_size // 2), dilation=dilation, norm_layer=norm_layer, act_layer=act_layer, **dd)
        self.add_identity = add_identity and in_channels == out_channels
        self.drop_path = DropPath(drop_path) if drop_path and self.add_identity else nn.Identity()

    def forward(self, x):
        out = self.conv2(self.conv1(x))
        if self.add_identity:
            out = self.drop_path(out) + x
        return out

class CspNextLayer(nn.Module):

    def __init__(self, in_channels, out_channels, expand_ratio=0.5, num_blocks=1, add_identity=True, channel_attention=False, dilation=1, drop_path_rates=None, norm_layer=nn.BatchNorm2d, act_layer=nn.SiLU, device=None, dtype=None):
        super().__init__()
        dd = {'device': device, 'dtype': dtype}
        mid_channels = int(out_channels * expand_ratio)
        self.short_conv = ConvNormAct(in_channels, mid_channels, 1, norm_layer=norm_layer, act_layer=act_layer, **dd)
        self.main_conv = ConvNormAct(in_channels, mid_channels, 1, norm_layer=norm_layer, act_layer=act_layer, **dd)
        self.blocks = nn.ModuleList([CspNextBlock(mid_channels, mid_channels, add_identity=add_identity, dilation=dilation, drop_path=drop_path_rates[i] if drop_path_rates is not None else 0.0, norm_layer=norm_layer, act_layer=act_layer, **dd) for i in range(num_blocks)])
        self.attention = EffectiveSEModule(2 * mid_channels, **dd) if channel_attention else nn.Identity()
        self.final_conv = ConvNormAct(2 * mid_channels, out_channels, 1, norm_layer=norm_layer, act_layer=act_layer, **dd)

    def forward(self, x):
        short = self.short_conv(x)
        main = self.main_conv(x)
        for block in self.blocks:
            main = block(main)
        x = torch.cat([main, short], dim=1)
        x = self.attention(x)
        return self.final_conv(x)

class CspNext(nn.Module):

    def __init__(self, in_chans=3, num_classes=1000, global_pool='avg', output_stride=32, drop_rate=0.0, drop_path_rate=0.0, depths=(3, 6, 6, 3), channels=(128, 256, 512, 1024), deepen_factor=1.0, widen_factor=1.0, expand_ratio=0.5, channel_attention=True, norm_layer=nn.BatchNorm2d, act_layer=nn.SiLU, device=None, dtype=None):
        super().__init__()
        if output_stride not in (8, 16, 32):
            raise ValueError(f'output_stride must be one of (8, 16, 32), got {output_stride}')
        if len(depths) != len(channels):
            raise ValueError('depths and channels must have the same length')
        dd = {'device': device, 'dtype': dtype}
        self.num_classes = num_classes
        self.in_chans = in_chans
        self.grad_checkpointing = False
        stage_depths = [max(round(d * deepen_factor), 1) for d in depths]
        stage_channels = [int(c * widen_factor) for c in channels]
        dpr = calculate_drop_path_rates(drop_path_rate, stage_depths[:-1], stagewise=True) + [None]
        stem_chs = max(stage_channels[0] // 2, 1)
        half_chs = max(stem_chs // 2, 1)
        self.stem = nn.Sequential(ConvNormAct(in_chans, half_chs, 3, stride=2, padding=1, norm_layer=norm_layer, act_layer=act_layer, **dd), ConvNormAct(half_chs, half_chs, 3, padding=1, norm_layer=norm_layer, act_layer=act_layer, **dd), ConvNormAct(half_chs, stem_chs, 3, padding=1, norm_layer=norm_layer, act_layer=act_layer, **dd))
        self.stages = nn.Sequential()
        self.feature_info = [dict(num_chs=stem_chs, reduction=2, module='stem')]
        net_stride = 2
        dilation = 1
        prev_chs = stem_chs
        num_stages = len(stage_channels)
        for i, (chs, num_blocks) in enumerate(zip(stage_channels, stage_depths)):
            stride = 2
            first_dilation = dilation
            if net_stride * 2 > output_stride:
                stride = 1
                dilation *= 2
            net_stride *= stride
            is_last = i == num_stages - 1
            layers = [ConvNormAct(prev_chs, chs, 3, stride=stride, padding=first_dilation, dilation=first_dilation, norm_layer=norm_layer, act_layer=act_layer, **dd)]
            if is_last:
                layers.append(SPPBottleneck(chs, chs, norm_layer=norm_layer, act_layer=act_layer, **dd))
            layers.append(CspNextLayer(chs, chs, expand_ratio=expand_ratio, num_blocks=num_blocks, add_identity=not is_last, channel_attention=channel_attention, dilation=dilation, drop_path_rates=dpr[i], norm_layer=norm_layer, act_layer=act_layer, **dd))
            self.stages.append(nn.Sequential(*layers))
            self.feature_info.append(dict(num_chs=chs, reduction=net_stride, module=f'stages.{i}'))
            prev_chs = chs
        self.num_features = prev_chs
        self.head = ClassifierHead(self.num_features, num_classes, pool_type=global_pool, drop_rate=drop_rate, **dd)
        self.head_hidden_size = self.head.num_features

    def forward_features(self, x):
        x = self.stem(x)
        if self.grad_checkpointing and (not torch.jit.is_scripting()):
            x = checkpoint_seq(self.stages, x)
        else:
            x = self.stages(x)
        return x

    def forward_head(self, x, pre_logits=False):
        return self.head(x, pre_logits=pre_logits)

    def forward(self, x):
        x = self.forward_features(x)
        x = self.forward_head(x)
        return x

def checkpoint_filter_fn(state_dict, model=None):
    state_dict = state_dict.get('state_dict', state_dict)
    out = {}
    for k, v in state_dict.items():
        k = re.sub('^backbone\\.', '', k)
        k = re.sub('^stage(\\d+)\\.', lambda m: f'stages.{int(m.group(1)) - 1}.', k)
        out[k] = v
    return out

def _create_cspnext(variant, pretrained=False, **kwargs):
    return build_model_with_cfg(CspNext, variant, pretrained, pretrained_filter_fn=checkpoint_filter_fn, feature_cfg=dict(out_indices=(0, 1, 2, 3, 4), feature_cls='getter'), **kwargs)

@register_model
def cspnext_s(pretrained=False, **kwargs):
    model_args = dict(deepen_factor=0.33, widen_factor=0.5)
    return _create_cspnext('cspnext_s', pretrained=pretrained, **dict(model_args, **kwargs))
model = cspnext_s()
