    def __init__(self, stem_stages, main_stages, in_chans=3, num_classes=1000, drop_rate=0.0, width_mult=1.0, norm_layer=None, output_stride=32):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
