    def __init__(self, features, num_classes=10, init_weights=True, dropout=0.5):
        super().__init__()
        self.features = features
        self.avgpool = nn.AdaptiveAvgPool2d((2, 2))
        self.classifier = nn.Sequential(nn.Linear(32 * 2 * 2, 32), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(32, 32), nn.ReLU(True), nn.Dropout(p=dropout), nn.Linear(32, num_classes))

    def forward(self, tensor):
        tensor = self.features(tensor)
        tensor = self.avgpool(tensor)
        tensor = torch.flatten(tensor, 1)
        tensor = self.classifier(tensor)
        return tensor
